#!/bin/sh
#
# OpenFoundry P2.5 — BUILD candidates (PG-track exclusive helper; Tools does
# NOT co-write this file). Root release 2026-11-15: BUILD-ONLY scope.
#
#   docker compose build:
#     base3        dataset, pipeline, connector   (q3 base compose only)
#     oldaux2      connector2, connector3         (base + frozen P22 override)
#     newaux1      p25connector                   (base + NEW P25 aux override,
#                  generated by this helper into THIS track dir — the q3
#                  fixture directory and every frozen yaml stay untouched)
#   python:3.12-alpine (dataset-proxy / fixture runtime image): LOCAL CACHE
#   INSPECT ONLY — no pull, no service start.
#
# Hard gates (evidence-first discipline, same family as
# run_pg_isolated_p25.sh):
#   - every command writes its REDACTED .cmd and .meta BEFORE execution;
#   - each build group saves its REAL docker rc; image identity is the FULL
#     sha256 Id from `docker image inspect` (never a running container's
#     image field, never a short ID);
#   - the whole helper is wrapped by a HARD source gate: the source content
#     hash must be IDENTICAL before and after AND equal EXPECT_SOURCE_SHA
#     (default: the accepted PG candidate a1bff07f…ffd27). Violation ⇒
#     wrapper rc=2, original rcs untouched;
#   - the q3 .env (mode 600) is ONLY sourced for compose interpolation and
#     its values / Config.Env / DSNs are never printed or archived;
#   - no up/down/restart/volume/secret changes; prod source untouched.

set -eu

SRC="${P25_SRC:-/Volumes/ExternalSD/projects/OpenFoundry}"
Q3="${P25_Q3:-/private/tmp/openfoundry-platform-p1-q3v9}"
PROJ="${P25_PROJECT:-openfoundry-platform-p1-q3v9}"
EV="${P25_BUILD_EVIDENCE:-/private/tmp/openfoundry-p25-repair-evidence/build}"
TRACK="$SRC/tools/smoke/business-platform-p2-5"
EXPECT_SHA="${P25_EXPECT_SOURCE_SHA:-a1bff07f3760fce7b5661b169ba26a165712c950035d4e4ec9948639d51ffd27}"
BASE_COMPOSE="$Q3/compose.yaml"
P22_COMPOSE="$Q3/compose-p22-connector2.yaml"
AUX_COMPOSE="$TRACK/build/compose-p25-aux.yaml"

mkdir -p "$EV" "$TRACK/build"

die() { printf '[p25-build] ERROR: %s\n' "$*" >&2; exit 2; }

now_utc() { date -u +%Y%m%dT%H%M%SZ; }

# Same deterministic source-content hash family as the PG runner (378 Go/SQL
# + module graph); build ignores evidence dirs.
source_tree_hash() {
  {
    printf 'go.mod\n'; cat "$SRC/go.mod"
    printf 'go.sum\n'; cat "$SRC/go.sum"
    printf 'content-hashes\n'
    find "$SRC/services/connector-management-service" \
         "$SRC/services/dataset-versioning-service" \
         "$SRC/services/pipeline-build-service" \
         "$SRC/libs/scheduling-cron" \
         -type f \( -name '*.go' -o -name '*.sql' \) -print0 \
      | sort -z | xargs -0 shasum -a 256
  } | shasum -a 256 | cut -d' ' -f1
}

fresh_attempt() {
  phase="$1"
  base="$EV/${phase}_$(now_utc)"
  n=1
  while [ -e "${base}.raw" ]; do
    n=$((n + 1)); base="$EV/${phase}_$(now_utc)-$n"
  done
  RAW="${base}.raw"; RCF="${base}.rc"; CMD="${base}.cmd"; META="${base}.meta"
}

write_meta() {
  phase="$1"; extra="${2:-}"
  {
    printf 'phase=%s\n' "$phase"
    printf 'utc=%s\n' "$(now_utc)"
    printf 'project=%s\n' "$PROJ"
    printf 'expect_source_sha=%s\n' "$EXPECT_SHA"
    printf 'base_compose=%s\n' "$BASE_COMPOSE"
    if [ -n "$extra" ]; then printf '%s\n' "$extra"; fi
  } > "$META"
  return 0
}

# ensure_env: the q3 .env must exist (mode 600, values never printed).
ensure_env() {
  [ -f "$Q3/.env" ] || die "q3 .env missing at $Q3/.env (never printed)"
}

# build_group <phase> <compose-args…> — cmd/meta BEFORE, real rc, then
# per-service FULL image sha via docker image inspect.
build_group() {
  phase="$1"; shift
  services="$1"; shift
  fresh_attempt "$phase"
  printf 'docker compose -p %s %s build %s (env sourced from %s/.env, values never printed)\n' \
    "$PROJ" "$*" "$services" "$Q3" > "$CMD"
  write_meta "$phase" "services=$services compose_args=$*"
  printf 'source_content_sha256_before=%s\n' "$(source_tree_hash)" >> "$META"
  rc=0
  # shellcheck disable=SC2086
  docker compose -p "$PROJ" "$@" build $services > "$RAW" 2>&1 || rc=$?
  printf '%s\n' "$rc" > "$RCF"
  printf 'source_content_sha256_after=%s\n' "$(source_tree_hash)" >> "$META"
  printf 'original_docker_rc=%s\n' "$rc" >> "$META"
  if [ "$rc" -ne 0 ]; then
    printf '[p25-build] %s FAILED rc=%s (raw %s; preserved)\n' "$phase" "$rc" "$RAW" >&2
    return "$rc"
  fi
  # Full image identity per service (docker image inspect, full sha256 Id).
  # compose v2 names build-only images "<project>-<service>:latest";
  # `compose images` is container-oriented and returns nonexistent refs when
  # nothing ever ran — inspect the deterministic tag directly (first-run
  # finding, helper fix).
  for svc in $services; do
    tag="${PROJ}-${svc}:latest"
    full=$(docker image inspect --format '{{.Id}}' "$tag" 2>/dev/null) || {
      printf 'image_lookup_failed=%s (%s)\n' "$svc" "$tag" >> "$META"
      return 1
    }
    printf 'image_sha[%s]=%s (tag %s)\n' "$svc" "$full" "$tag" >> "$META"
  done
  printf '[p25-build] %s: rc=0 (raw %s)\n' "$phase" "$RAW"
  return 0
}

# cache_inspect <phase> <image>: LOCAL cache only — inspect, never pull/start.
cache_inspect() {
  phase="$1"; image="$2"
  fresh_attempt "$phase"
  printf 'docker image inspect --format {{.Id}} %s (LOCAL CACHE ONLY — no pull, no start)\n' \
    "$image" > "$CMD"
  write_meta "$phase" "image_ref=$image pull=forbidden start=forbidden"
  rc=0
  full=$(docker image inspect --format '{{.Id}}' "$image" > "$RAW" 2>&1) || rc=$?
  if [ "$rc" -eq 0 ]; then
    full=$(cat "$RAW")
    printf 'image_sha=%s\n' "$full" >> "$META"
  fi
  printf '%s\n' "$rc" > "$RCF"
  printf '[p25-build] %s: rc=%s (cache inspect only)\n' "$phase" "$rc"
  return "$rc"
}

case "${1:-}" in

all)
  ensure_env
  HASH_BEFORE="$(source_tree_hash)"
  [ "$HASH_BEFORE" = "$EXPECT_SHA" ] \
    || die "source gate: tree is '$HASH_BEFORE', expected '$EXPECT_SHA' — refusing to build a foreign candidate"

  # Generate the NEW P25 aux override (this track dir; q3 untouched).
  fresh_attempt "render-aux"
  printf 'generate %s (NEW file; frozen yamls untouched)\n' "$AUX_COMPOSE" > "$CMD"
  write_meta "render-aux" "output=$AUX_COMPOSE"
  mkdir -p "$TRACK/build"
  cat > "$AUX_COMPOSE" << 'YAML'
# P25 aux override — GENERATED by build_candidates_p25.sh (PG track).
# BUILD-ONLY artifact for the p25connector service; the q3 fixture dir and
# every frozen compose file stay untouched. Not used by any up/down path.
services:
  p25connector:
    networks:
      p1net: {}
    build:
      context: "/Volumes/ExternalSD/projects/OpenFoundry"
      dockerfile: /Volumes/ExternalSD/projects/OpenFoundry/tools/smoke/business-platform-p1/service.Dockerfile
      args:
        SERVICE_NAME: connector-management-service
    environment:
      HOST: 0.0.0.0
      PORT: 50088
      DATABASE_URL: postgres://openfoundry:${OF_P1_PG_PASSWORD:?}@postgres:5432/connectors
      JWT_SECRET: ${OF_P1_JWT_SECRET:?}
      DATASET_SERVICE_URL: http://dataset:50078
      CREDENTIAL_ENCRYPTION_KEY: ${OF_P1_CREDENTIAL_KEY:?}
      ALLOW_PRIVATE_NETWORK_EGRESS: "true"
      ALLOWED_EGRESS_HOSTS: fixture
YAML
  shasum -a 256 "$AUX_COMPOSE" > "$RAW"
  printf '0\n' > "$RCF"

  # shellcheck disable=SC1091
  set -a; . "$Q3/.env"; set +a   # values never printed

  build_group build-base3     "dataset pipeline connector" -f "$BASE_COMPOSE"
  build_group build-oldaux2   "connector2 connector3"     -f "$BASE_COMPOSE" -f "$P22_COMPOSE"
  build_group build-newaux1   "p25connector"              -f "$BASE_COMPOSE" -f "$AUX_COMPOSE"
  cache_inspect cache-python312alpine "python:3.12-alpine"

  HASH_AFTER="$(source_tree_hash)"
  fresh_attempt "source-gate"
  printf 'hard source gate: before==after==expect\n' > "$CMD"
  write_meta "source-gate" "checker=inline"
  printf 'source_content_sha256_before=%s\nsource_content_sha256_after=%s\nexpect_source_sha=%s\n' \
    "$HASH_BEFORE" "$HASH_AFTER" "$EXPECT_SHA" > "$RAW"
  gate=0
  [ "$HASH_BEFORE" = "$HASH_AFTER" ] && [ "$HASH_AFTER" = "$EXPECT_SHA" ] || gate=1
  printf 'source_gate_rc=%s\n' "$gate" >> "$RAW"
  printf '%s\n' "$gate" > "$RCF"
  [ "$gate" -eq 0 ] || die "SOURCE GATE FAILED (see $RAW) — original build rcs untouched"
  printf '[p25-build] all groups built; source gate OK (%s)\n' "$EXPECT_SHA"
  ;;

status)
  printf 'evidence dir: %s\n' "$EV"
  ls -l "$EV" | tail -n +2 || true
  ;;

*)
  sed -n '2,30p' "$0" | grep -E '^#( |$)' || true
  die "usage: $0 all|status"
  ;;
esac
